package com.jnapanam.sportszone.training.model;import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="training_attendance",uniqueConstraints=@UniqueConstraint(name="uq_training_attendance",columnNames={"enrollment_id","session_date"}))public class TrainingAttendance{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="enrollment_id")private TrainingEnrollment enrollment;@Column(name="session_date",nullable=false)private LocalDate sessionDate;@Column(nullable=false)private boolean present;@Column(name="marked_at",nullable=false)private Instant markedAt;protected TrainingAttendance(){}public TrainingAttendance(TrainingEnrollment e,LocalDate d,boolean p){id=UUID.randomUUID();enrollment=e;sessionDate=d;mark(p);}public void mark(boolean p){present=p;markedAt=Instant.now();}public LocalDate getSessionDate(){return sessionDate;}public boolean isPresent(){return present;}}
